// Ported from the Node app's Sequelize model BiometricDevice (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class BiometricDeviceConfiguration : IEntityTypeConfiguration<BiometricDevice>
{
    public void Configure(EntityTypeBuilder<BiometricDevice> builder)
    {
        builder.ToTable("biometric_devices", t =>
        {
            t.HasCheckConstraint("CK_biometric_devices_status", "[status] IN (N'active', N'inactive')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(80)").HasMaxLength(80).IsRequired();
        builder.Property(e => e.SerialNo).HasColumnName("serial_no").HasColumnType("nvarchar(60)").HasMaxLength(60).IsRequired();
        builder.Property(e => e.Location).HasColumnName("location").HasColumnType("nvarchar(120)").HasMaxLength(120);
        builder.Property(e => e.ApiKey).HasColumnName("api_key").HasColumnType("nvarchar(64)").HasMaxLength(64).IsRequired();
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'active'");
        builder.Property(e => e.LastSeenAt).HasColumnName("last_seen_at").HasColumnType("datetime2");
        builder.HasIndex(e => e.SerialNo).IsUnique();
        builder.HasIndex(e => e.ApiKey).IsUnique();
    }
}
